"""Real model regression against vectors generated by FastEmbed 0.9.0."""
import json
import os
from pathlib import Path
import unittest

import numpy as np
from bge_embedding import BgeTextEmbedding, MODEL_REVISION


@unittest.skipUnless(os.getenv('VERIFY_BGE_MODEL') == '1', 'Enable the real ONNX model check explicitly')
class BgeModelTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.fixture = json.loads((Path(__file__).parent / 'fixtures/bge-fastembed-reference.json').read_text())
        cls.model = BgeTextEmbedding(cache_dir=os.path.expanduser(os.getenv('FASTEMBED_CACHE_PATH', '~/.cache/f1-bge')))

    def test_existing_vectors_remain_compatible_including_empty_unicode_and_truncation(self):
        self.assertEqual(self.fixture['revision'], MODEL_REVISION)
        actual = np.asarray(list(self.model.embed(self.fixture['texts'], batch_size=6)))
        expected = np.asarray(self.fixture['vectors'])
        self.assertEqual(actual.shape, (6, 384))
        # Quantized kernels can differ slightly across CPU architectures.
        similarity = np.sum(actual * expected, axis=1)
        np.testing.assert_allclose(similarity, np.ones(6), atol=0.002, rtol=0)
        np.testing.assert_allclose(np.linalg.norm(actual, axis=1), np.ones(6), atol=1e-6)

    def test_empty_input_single_string_and_batch_boundaries(self):
        self.assertEqual(list(self.model.embed([])), [])
        self.assertEqual(len(list(self.model.embed('race report'))), 1)
        vectors = list(self.model.embed(['report'] * 65))
        self.assertEqual(len(vectors), 65)
        self.assertTrue(all(vector.shape == (384,) for vector in vectors))
        with self.assertRaises(ValueError):
            list(self.model.embed(['report'], batch_size=0))
        with self.assertRaises(TypeError):
            list(self.model.embed([b'not text']))


if __name__ == '__main__':
    unittest.main()
